import csv, math

base = '/filesystem/field_eng__constructability_4d__blind'
def load_csv(rel):
    with open(f'{base}/{rel}') as f:
        return list(csv.DictReader(f))

zones = {r['zone_id']: r for r in load_csv('model/zone_schedule.csv')}
zws = load_csv('programme/zone_work_schedule.csv')
cpos = load_csv('site/crane_standing_positions.csv')
cchart = [(float(r['radius_ft']), float(r['rated_capacity_lb'])) for r in load_csv('site/crane_chart.csv')]

def interp_cap(r):
    if r <= cchart[0][0]:
        return cchart[0][1]
    if r > cchart[-1][0]:
        return 0.0
    for i in range(len(cchart)-1):
        r0, c0 = cchart[i]
        r1, c1 = cchart[i+1]
        if r0 <= r <= r1:
            return c0 + (c1 - c0) * (r - r0) / (r1 - r0)
    return 0.0

for zn_id, zn in zones.items():
    cx = 0.5 * (float(zn['x0_ft']) + float(zn['x1_ft']))
    cy = 0.5 * (float(zn['y0_ft']) + float(zn['y1_ft']))
    # max pick across L2, L3, L4 for this zone
    picks = [float(r['heaviest_pick_lb']) for r in zws if r['zone'] == zn_id]
    max_pick = max(picks)
    print(f'=== {zn_id} (centroid=({cx:.2f}, {cy:.2f}), max_pick={max_pick} lb) ===')
    for cp in cpos:
        pid = cp['position_id']
        px, py = float(cp['x_ft']), float(cp['y_ft'])
        dist = math.hypot(cx - px, cy - py)
        cap = interp_cap(dist)
        ok = (dist <= float(cp['max_radius_ft'])) and (cap >= max_pick)
        print(f'  {pid} ({px},{py}): radius={dist:.2f} ft, cap={cap:.1f} lb, ok={ok}')
"

